"""Offline registration organizer; Python standard library only."""
import csv
import io
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
COLUMNS = ["submission_id", "活动", "姓名", "邮箱"]


def read_csv(path):
    raw = path.read_bytes()
    try:
        data = raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        try:
            data = raw.decode("gb18030")
        except UnicodeDecodeError as exc:
            raise ValueError(f"{path.name}：无法识别编码，请另存为 UTF-8 CSV。") from exc
    reader = csv.reader(io.StringIO(data, newline=""), strict=True)
    try:
        header = next(reader, None)
        if header is None or len(header) != len(set(header)) or set(header) != set(COLUMNS):
            raise ValueError(f"{path.name}：表头必须包含且仅包含 {','.join(COLUMNS)}。")
        for row in reader:
            line = reader.line_num
            if not row:
                continue
            if len(row) != len(header):
                raise ValueError(f"{path.name} 第 {line} 行：列数不正确。")
            record = dict(zip(header, row))
            if not record["submission_id"].strip():
                raise ValueError(f"{path.name} 第 {line} 行：缺少 submission_id，无法判断重复。")
            yield record, f"{path.name} 第 {line} 行"
    except csv.Error as exc:
        raise ValueError(f"{path.name} 第 {reader.line_num} 行：CSV 格式错误：{exc}") from exc


def spreadsheet_value(value):
    # Prevent spreadsheet formula execution, leaving normal names/emails untouched.
    if value.lstrip().startswith(("=", "+", "-", "@")) or value.startswith(("\t", "\r", "\n")):
        return "'" + value
    return value


def write_csv(path, header, rows):
    with path.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.writer(stream)
        writer.writerow(header)
        for row in rows:
            writer.writerow([spreadsheet_value(v) if isinstance(v, str) else v for v in row])


def organize(input_dir, output_dir):
    files = sorted(input_dir.glob("*.csv"))
    if not files:
        raise ValueError("inputs 中没有 CSV 文件。请放入报名表后重试。")
    unique = {}
    origins = {}
    total = 0
    for path in files:
        for record, origin in read_csv(path):
            total += 1
            key = record["submission_id"]
            if key in unique:
                if record != unique[key]:
                    raise ValueError(f"编号 {key!r} 内容冲突：{origins[key]} 与 {origin}。请核对原表；未生成本次结果。")
                continue
            unique[key] = record
            origins[key] = origin
    groups = {}
    for record in unique.values():
        groups.setdefault(record["活动"], []).append(record)
    # Validate every input before creating any output.
    output_dir.mkdir(parents=True, exist_ok=True)
    result = output_dir / datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    result.mkdir()
    write_csv(result / "活动人数.csv", ["活动", "人数"],
              [(activity, len(records)) for activity, records in sorted(groups.items())])
    write_csv(result / "报名名单.csv", ["活动", "submission_id", "姓名", "邮箱"],
              [[r[c] for c in ["活动", "submission_id", "姓名", "邮箱"]]
               for _, records in sorted(groups.items()) for r in records])
    missing = {c: sum(not r[c].strip() for r in unique.values()) for c in COLUMNS[1:]}
    status = (f"来源：{', '.join(p.name for p in files)}\n"
              f"原始记录：{total}\n重复记录：{total - len(unique)}\n有效报名：{len(unique)}\n"
              + "".join(f"空{c}：{n}\n" for c, n in missing.items())
              + "规则来源：inputs/说明.md；相同编号且内容相同仅计一次，不同编号分别计数。\n"
              + "人数按报名编号统计，不代表经过身份核验的独立自然人数。\n"
              + "空活动在人数表和名单中仍留空，未猜测或补填。\n"
              + "CSV 为 UTF-8 BOM；可能被表格软件当作公式的文本加前置单引号。\n")
    (result / "整理记录.txt").write_text(status, encoding="utf-8-sig")
    return result, total, len(unique)


def main():
    try:
        result, total, count = organize(ROOT / "inputs", ROOT / "outputs")
        print(f"整理完成：{total} 条记录，去重后 {count} 条，重复 {total-count} 条。")
        print(f"结果目录：{result}")
        return 0
    except (ValueError, OSError) as exc:
        print(f"整理失败：{exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

