                if record != unique[key]:
                    raise ValueError(f"编号 {key!r} 内容冲突：{origins[key]} 与 {origin}。请核对原表；未生成本次结果。")
                continue
            unique[key] = record
            origins[key] = origin
    groups = {}
    for record in unique.values():
        groups.setdefault(record["活动"], []).append(record)
    # Validate every input before creating any output.
    output_dir.mkdir(parents=True, exist_ok=True)
    result = output_dir / datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    result.mkdir()
    write_csv(result / "活动人数.csv", ["活动", "人数"],
              [(activity, len(records)) for activity, records in sorted(groups.items())])
    write_csv(result / "报名名单.csv", ["活动", "submission_id", "姓名", "邮箱"],
              [[r[c] for c in ["活动", "submission_id", "姓名", "邮箱"]]
               for _, records in sorted(groups.items()) for r in records])
    missing = {c: sum(not r[c].strip() for r in unique.values()) for c in COLUMNS[1:]}
    status = (f"来源：{', '.join(p.name for p in files)}\n"
              f"原始记录：{total}\n重复记录：{total - len(unique)}\n有效报名：{len(unique)}\n"
              + "".join(f"空{c}：{n}\n" for c, n in missing.items())
              + "规则来源：inputs/说明.md；相同编号且内容相同仅计一次，不同编号分别计数。\n"
              + "人数按报名编号统计，不代表经过身份核验的独立自然人数。\n"
              + "空活动在人数表和名单中仍留空，未猜测或补填。\n"
              + "CSV 为 UTF-8 BOM；可能被表格软件当作公式的文本加前置单引号。\n")
    (result / "整理记录.txt").write_text(status, encoding="utf-8-sig")
    return result, total, len(unique)


def main():
    try:
        result, total, count = organize(ROOT / "inputs", ROOT / "outputs")
        print(f"整理完成：{total} 条记录，去重后 {count} 条，重复 {total-count} 条。")
