"""Offline registration organizer; Python standard library only."""
from pathlib import Path
import csv
import io
import sys
import zipfile
from datetime import datetime
from xml.sax.saxutils import escape

ROOT = Path(__file__).resolve().parent
HEADERS = ['submission_id', '活动', '姓名', '邮箱']


def read_registrations(folder):
    files = sorted(folder.glob('*.csv'))
    if not files:
        raise ValueError('inputs 中没有 CSV 文件。请放入报名表后重试。')
    records = {}
    total = 0
    duplicates = 0
    for path in files:
        raw = path.read_bytes()
        try:
            content = raw.decode('utf-8-sig', errors='strict')
        except UnicodeDecodeError:
            raise ValueError(f'{path.name} 不是 UTF-8 CSV。请在表格软件中另存为 CSV UTF-8。')
        reader = csv.DictReader(io.StringIO(content, newline=''), strict=True)
        if reader.fieldnames != HEADERS:
            raise ValueError(f'{path.name} 的表头应为：' + ','.join(HEADERS))
        for row in reader:
            total += 1
            if None in row or any(value is None for value in row.values()):
                raise ValueError(f'{path.name} 第 {reader.line_num} 行列数不正确。')
            key = row['submission_id']
            if not key.strip():
                raise ValueError(f'{path.name} 第 {reader.line_num} 行缺少 submission_id，无法可靠去重。')
            if key in records:
                if row != records[key]:
                    raise ValueError(f'编号 {key} 的重复提交内容不一致，请核对原表。此次不导出。')
                duplicates += 1
            else:
                records[key] = row
    return list(records.values()), total, duplicates, len(files)


def column_name(number):
    name = ''
    while number:
        number, remainder = divmod(number - 1, 26)
        name = chr(65 + remainder) + name
    return name


def sheet_xml(rows):
    body = []
    for row_number, row in enumerate(rows, 1):
        cells = []
        for col, value in enumerate(row, 1):
            ref = f'{column_name(col)}{row_number}'
            if isinstance(value, int):
                cells.append(f'<c r="{ref}"><v>{value}</v></c>')
            else:
                # Explicit strings preserve Chinese, identifiers and formula-like names.
                value = str(value)
                if any(ord(c) < 32 and c not in '\t\n\r' for c in value):
                    raise ValueError('输入含有表格不支持的控制字符。')
                if len(value) > 32767:
                    raise ValueError('某个单元格超过 Excel 的 32767 字符限制。')
                cells.append(f'<c r="{ref}" t="inlineStr"><is><t xml:space="preserve">{escape(value)}</t></is></c>')
        body.append(f'<row r="{row_number}">' + ''.join(cells) + '</row>')
    if len(rows) > 1048576:
        raise ValueError('名单超过 Excel 单张工作表的行数限制。')
    return ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
            '<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews>'
            '<cols><col min="1" max="4" width="28" customWidth="1"/></cols><sheetData>'
            + ''.join(body) + '</sheetData></worksheet>')


def workbook_bytes(sheets):
    out = io.BytesIO()
    with zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as archive:
        overrides = ''.join(f'<Override PartName="/xl/worksheets/sheet{i}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' for i in range(1, len(sheets) + 1))
        archive.writestr('[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>' + overrides + '</Types>')
        archive.writestr('_rels/.rels', '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
        entries = ''.join(f'<sheet name="{name}" sheetId="{i}" r:id="rId{i}"/>' for i, (name, rows) in enumerate(sheets, 1))
        archive.writestr('xl/workbook.xml', '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>' + entries + '</sheets></workbook>')
        relations = ''.join(f'<Relationship Id="rId{i}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{i}.xml"/>' for i in range(1, len(sheets) + 1))
        archive.writestr('xl/_rels/workbook.xml.rels', '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' + relations + '</Relationships>')
        for i, (name, rows) in enumerate(sheets, 1):
            archive.writestr(f'xl/worksheets/sheet{i}.xml', sheet_xml(rows))
    return out.getvalue()


def main():
    records, total, duplicates, file_count = read_registrations(ROOT / 'inputs')
    groups = {}
    for record in records:
        groups.setdefault(record['活动'], []).append(record)
    summary = [['活动', '人数', '名单工作表']]
    sheets = []
    for index, (activity, people) in enumerate(groups.items(), 1):
        name = f'名单{index}'
        summary.append([activity, len(people), name])
        sheets.append((name, [HEADERS] + [[p[h] for h in HEADERS] for p in people]))
    summary += [['合计', len(records), ''], ['读取文件数', file_count, ''], ['原始报名行数', total, ''], ['重复行数', duplicates, '']]
    payload = workbook_bytes([('人数汇总', summary)] + sheets)
    folder = ROOT / 'outputs' / datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    folder.mkdir(parents=True, exist_ok=False)
    destination = folder / '报名整理.xlsx'
    destination.write_bytes(payload)
    print(f'完成：{total} 行，去除重复 {duplicates} 行，有效报名 {len(records)} 人。')
    print(f'结果：{destination}')


if __name__ == '__main__':
    try:
        main()
    except (ValueError, OSError, csv.Error) as error:
        print(f'处理失败：{error}', file=sys.stderr)
        sys.exit(1)

